-- ----------------------------
-- Table structure for kc_device
-- ----------------------------
DROP TABLE IF EXISTS `kc_device`;
CREATE TABLE `kc_device`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '设备ID',
  `device_code` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '设备编码',
  `qrcode_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '设备二维码地址',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '设备名称',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '设备描述',
  `merchant_id` bigint NULL DEFAULT NULL COMMENT '绑定商家ID',
  `agent_id` bigint NULL DEFAULT NULL COMMENT '绑定代理ID',
  `device_status` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL COMMENT '设备信息(烤盘状态JSON)',
  `business_hours` varchar(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '营业时间',
  `address` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '设备地址',
  `longitude` decimal(10, 7) NULL DEFAULT NULL COMMENT '经度',
  `latitude` decimal(10, 7) NULL DEFAULT NULL COMMENT '纬度',
  `mqtt_url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT 'mqtt链接地址',
  `mqtt_username` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT 'mqtt账号',
  `mqtt_password` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT 'mqtt密码',
  `modbus_address` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '设备modbus地址',
  `total_sales` int NULL DEFAULT 0 COMMENT '累计销量',
  `total_sales_amount` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '累计销量金额',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '后台启停状态（0正常/启用 1停用）',
  `online_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '营业状态（0待投运 1运营中 2休息中 3维护中 4工作中/正在出餐）',
  `concurrency_mode` tinyint(1) NULL DEFAULT 1 COMMENT '1低并发模式，2高并发模式',
  `transition_mode` tinyint(1) NULL DEFAULT 0 COMMENT '0是默认，1是低并发过渡到高并发，2是高并发过渡到低并发',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_device_code`(`device_code` ASC) USING BTREE,
  INDEX `idx_merchant_id`(`merchant_id` ASC) USING BTREE,
  INDEX `idx_agent_id`(`agent_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 109 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '设备管理表' ROW_FORMAT = Dynamic;

