-- ----------------------------
-- Table structure for kc_order
-- ----------------------------
DROP TABLE IF EXISTS `kc_order`;
CREATE TABLE `kc_order`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '订单ID',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '订单编号',
  `user_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '用户ID',
  `device_id` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '设备ID',
  `device_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '设备名称',
  `merchant_id` bigint NULL DEFAULT NULL COMMENT '商户ID',
  `agent_id` bigint NULL DEFAULT NULL COMMENT '代理ID',
  `amount` decimal(10, 2) NOT NULL COMMENT '订单总金额',
  `merchant_amount` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '商户分成总金额',
  `agent_amount` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '代理分成总金额',
  `platform_amount` decimal(10, 2) NULL DEFAULT 0.00 COMMENT '平台分成总金额',
  `points_gift` int NULL DEFAULT 0 COMMENT '赠送总积分',
  `product_count` int NULL DEFAULT 0 COMMENT '商品总数量',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '0' COMMENT '状态（0待付款，1夹取中 2请取肠 3已完成 4已取消 5退款中，6退款完成）',
  `pay_status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '0' COMMENT '支付状态（0待支付 1已支付）',
  `pay_time` datetime NULL DEFAULT NULL COMMENT '支付时间',
  `pay_type` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '支付方式（1微信 2支付宝）',
  `transaction_id` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT '' COMMENT '交易流水号',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `update_time` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NULL DEFAULT NULL COMMENT '备注',
  `product_count_finish` int NULL DEFAULT 0 COMMENT '当前已完成的烤肠数量',
  `retrue_amount` decimal(10, 2) NULL DEFAULT NULL COMMENT '退款金额',
  `deduct_points` int NULL DEFAULT NULL COMMENT '抵扣积分',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `idx_order_no`(`order_no` ASC) USING BTREE,
  INDEX `idx_user_id`(`user_id` ASC) USING BTREE,
  INDEX `idx_device_id`(`device_id` ASC) USING BTREE,
  INDEX `idx_merchant_id`(`merchant_id` ASC) USING BTREE,
  INDEX `idx_agent_id`(`agent_id` ASC) USING BTREE,
  INDEX `idx_create_time`(`create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 167 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_0900_ai_ci COMMENT = '订单主表' ROW_FORMAT = Dynamic;

